23	static void fmt_f1(char * buf, size_t n, float v)
24	{
25	    int vi = (int)v;
26	    int vf = (int)((v - (float)vi) * 10.0f);
27	    if(vf < 0) vf = -vf;
28	    lv_snprintf(buf, n, "%d.%d", vi, vf);
29	}
