43	static void refresh_alarm(void * user)
44	{
45	    const vg_alarm_t * a;
46	    const vg_sensor_t * s = NULL;
47	    const vg_sensor_t * as;
48	    char buf[160];
49	    char a1[16];
50	    int i;
51	    int start;
52	    int npts;
53	    uint16_t sensor_n = 0;
54	    LV_UNUSED(user);
55	    if(vg_nav_current() != VG_PAGE_ALARM) return;
56	    if(s_alarm_ui.root == NULL || !lv_obj_is_valid(s_alarm_ui.root)) return;
57	
58	    a = vg_model_get_active_alarm();
59	    vg_model_get_sensors(&sensor_n);
60	    if(sensor_n > 0) {
61	        s = vg_model_get_primary_sensor();
62	    }
63	
64	    if(a == NULL) {
65	        lv_label_set_text(s_alarm_ui.title, "无活动告警");
66	        vg_status_chip_set(s_alarm_ui.chip, "正常", VG_SEV_OK);
67	        set_ai_text("【规则摘要】暂无告警上下文。");
68	        return;
69	    }
70	
71	    as = NULL;
72	    if(a->sensor_id[0] != '\0') {
73	        as = vg_model_get_sensor(a->sensor_id);
74	    }
75	    if(as == NULL) {
76	        as = s;
77	    }
78	
79	    if(a->active) {
80	        lv_label_set_text(s_alarm_ui.title, a->title);
81	        vg_status_chip_set(s_alarm_ui.chip, vg_severity_label_zh(a->severity), a->severity);
82	
83	        vg_metric_row_set_value(s_alarm_ui.rows[0],
84	                                a->severity == VG_SEV_OFFLINE ? "通信离线" : "阈值越限");
85	
86	        if(a->severity == VG_SEV_OFFLINE || as == NULL) {
87	            vg_metric_row_set_value(s_alarm_ui.rows[1], "--");
88	            vg_metric_row_set_value(s_alarm_ui.rows[2], "--");
89	        }
90	        else {
91	            fmt_f1(a1, sizeof(a1), a->value);
92	            lv_snprintf(buf, sizeof(buf), "%s %s", a1, as->unit);
93	            vg_metric_row_set_value(s_alarm_ui.rows[1], buf);
94	
95	            fmt_f1(a1, sizeof(a1), a->threshold);
96	            lv_snprintf(buf, sizeof(buf), "%s %s", a1, as->unit);
97	            vg_metric_row_set_value(s_alarm_ui.rows[2], buf);
98	        }
99	
100	        lv_snprintf(buf, sizeof(buf), "%d s", a->duration_sec);
101	        vg_metric_row_set_value(s_alarm_ui.rows[3], buf);
102	        vg_metric_row_set_value(s_alarm_ui.rows[4], as ? as->name : "--");
103	        vg_metric_row_set_value(s_alarm_ui.rows[5],
104	                                a->acked ? "已处理" : (a->muted ? "已静音" : "活动中"));
105	
106	        npts = 0;
107	        if(as != NULL) {
108	            npts = 8;
109	            if(as->history_len < npts) npts = as->history_len;
110	            start = (int)as->history_len - npts;
111	            if(start < 0) start = 0;
112	            buf[0] = '\0';
113	            for(i = 0; i < npts; i++) {
114	                char p[12];
115	                fmt_f1(p, sizeof(p), as->history[start + i]);
116	                if(i == 0) {
117	                    lv_snprintf(buf, sizeof(buf), "%s", p);
118	                }
119	                else {
120	                    size_t len = strlen(buf);
121	                    lv_snprintf(buf + len, sizeof(buf) - len, " %s", p);
122	                }
123	            }
124	        }
125	        if(npts == 0) {
126	            lv_label_set_text(s_alarm_ui.hist_lab, "历史: --");
127	        }
128	        else {
129	            char full[128];
130	            lv_snprintf(full, sizeof(full), "历史: %s", buf);
131	            lv_label_set_text(s_alarm_ui.hist_lab, full);
132	        }
133	
134	        if(as != NULL && a->severity != VG_SEV_OFFLINE) {
135	            lv_snprintf(buf, sizeof(buf),
136	                        "【规则摘要】%s 当前 %.1f%s，阈值 %.1f%s，已持续 %d 秒。"
137	                        "判定来自点表 cmp/阈值，本地规则引擎。",
138	                        as->name, (double)a->value, as->unit,
139	                        (double)a->threshold, as->unit, a->duration_sec);
140	        }
141	        else if(a->severity == VG_SEV_OFFLINE) {
142	            lv_snprintf(buf, sizeof(buf),
143	                        "【规则摘要】滑窗读失败达阈值，离线已持续 %d 秒。",
144	                        a->duration_sec);
145	        }
146	        else {
147	            lv_snprintf(buf, sizeof(buf),
148	                        "【规则摘要】有活动告警，但本地尚无该点读数。");
149	        }
150	        set_ai_text(buf);
151	
152	        if(s_alarm_ui.btn_ack) {
153	            if(a->acked) {
154	                lv_obj_add_state(s_alarm_ui.btn_ack, LV_STATE_DISABLED);
155	            }
156	            else {
157	                lv_obj_remove_state(s_alarm_ui.btn_ack, LV_STATE_DISABLED);
158	            }
159	        }
160	        if(s_alarm_ui.btn_mute) {
161	            if(a->muted) {
162	                lv_obj_add_state(s_alarm_ui.btn_mute, LV_STATE_DISABLED);
163	            }
164	            else {
165	                lv_obj_remove_state(s_alarm_ui.btn_mute, LV_STATE_DISABLED);
166	            }
167	        }
168	    }
169	    else {
170	        lv_label_set_text(s_alarm_ui.title, "无活动告警");
171	        vg_status_chip_set(s_alarm_ui.chip, "正常", VG_SEV_OK);
172	        vg_metric_row_set_value(s_alarm_ui.rows[0], "--");
173	        vg_metric_row_set_value(s_alarm_ui.rows[1], "--");
174	        vg_metric_row_set_value(s_alarm_ui.rows[2], "--");
175	        vg_metric_row_set_value(s_alarm_ui.rows[3], "--");
176	        vg_metric_row_set_value(s_alarm_ui.rows[4], as ? as->name : "--");
177	        vg_metric_row_set_value(s_alarm_ui.rows[5], "无");
178	        lv_label_set_text(s_alarm_ui.hist_lab, "历史: --");
179	        set_ai_text("【规则摘要】当前无活动告警。");
180	        if(s_alarm_ui.btn_ack) lv_obj_add_state(s_alarm_ui.btn_ack, LV_STATE_DISABLED);
181	        if(s_alarm_ui.btn_mute) lv_obj_add_state(s_alarm_ui.btn_mute, LV_STATE_DISABLED);
182	    }
183	}
