206	static lv_obj_t * make_btn(lv_obj_t * parent, const char * text, bool primary, lv_event_cb_t cb)
207	{
208	    lv_obj_t * btn = lv_button_create(parent);
209	    lv_obj_set_size(btn, 140, VG_MIN_TOUCH_H);
210	    lv_obj_set_style_min_height(btn, VG_MIN_TOUCH_H, 0);
211	    lv_obj_set_style_max_height(btn, VG_MIN_TOUCH_H, 0);
212	    vg_style_apply_btn(btn, primary);
213	    lv_obj_t * lab = lv_label_create(btn);
214	    lv_label_set_text(lab, text);
215	    lv_obj_set_style_text_font(lab, vg_font_ui(), 0);
216	    lv_obj_center(lab);
217	    if(cb) lv_obj_add_event_cb(btn, cb, LV_EVENT_CLICKED, NULL);
218	    return btn;
219	}
