102	static float approx_sin(float t)
103	{
104	    int phase = ((int)(t * 10.0f) % 62 + 62) % 62;
105	    if(phase < 16) return (float)phase / 16.0f;
106	    if(phase < 31) return (float)(31 - phase) / 15.0f;
107	    if(phase < 47) return -(float)(phase - 31) / 16.0f;
108	    return -(float)(62 - phase) / 15.0f;
109	}
