111	static void fill_sensor_history(vg_sensor_t * s, float base, float amp, float noise)
112	{
113	    int i;
114	    if(s == NULL) return;
115	    s->history_len = VG_HISTORY_LEN;
116	    for(i = 0; i < VG_HISTORY_LEN; i++) {
117	        float t = (float)i / 8.0f;
118	        float n = ((float)((i * 17 + (int)s_tick * 3 + (int)s->reg_addr) % 11) - 5.0f) * noise;
119	        s->history[i] = base + amp * approx_sin(t) + n;
120	    }
121	    s->value = s->history[VG_HISTORY_LEN - 1];
122	}
