1664	bool vg_model_set_live(uint16_t idx, float value, bool online)
1665	{
1666	    vg_sensor_t * s;
1667	    bool changed = false;
1668	
1669	    if(idx >= s_sensor_n) {
1670	        return false;
1671	    }
1672	
1673	    s = &s_sensors[idx];
1674	    if(online) {
1675	        if(s->fail_streak != 0) {
1676	            s->fail_streak = 0;
1677	            changed = true;
1678	        }
1679	        if(!s->online || s->value != value) {
1680	            changed = true;
1681	        }
1682	        s->online = true;
1683	        s->value = value;
1684	        s->base_value = value;
1685	        s->age_sec = 1;
1686	        s->quality_pct = 95;
1687	#ifdef VG_HMI_BOARD
1688	        s_net.acq_ok = true;
1689	        vg_offline_win_push(s, false);
1690	        {
1691	            struct vg_alarm_rule rule;
1692	            enum vg_alarm_kind kind;
1693	            float thr = 0.0f;
1694	            vg_severity_t sev;
1695	            const char * title;
1696	            int rank;
1697	
1698	            memset(&rule, 0, sizeof(rule));
1699	            strncpy(rule.cmp, s->cmp, sizeof(rule.cmp) - 1);
1700	            rule.has_warn = s->has_warn;
1701	            rule.has_crit = s->has_crit;
1702	            rule.warn = s->thr_warn;
1703	            rule.crit = s->thr_crit;
1704	            rule.fail_n = s->fail_n;
1705	            kind = vg_alarm_eval(&rule, 1, 0, value, &thr);
1706	            /* Recovery: this point owns the active alarm and reads normal */
1707	            if(kind == VG_ALARM_KIND_NONE && s_alarm.active &&
1708	               strcmp(s_alarm.sensor_id, s->id) == 0) {
1709	                char logbuf[96];
1710	
1711	                lv_snprintf(logbuf, sizeof(logbuf), "告警恢复: %s", s->name);
1712	                memset(&s_alarm, 0, sizeof(s_alarm));
1713	                vg_model_append_log(VG_LOG_ALARM, VG_SEV_OK, logbuf);
1714	                changed = true;
1715	            }
1716	            if(kind == VG_ALARM_KIND_CRIT) {
1717	                sev = VG_SEV_CRIT;
1718	                title = "点表严重告警";
1719	            }
1720	            else if(kind == VG_ALARM_KIND_WARN) {
1721	                sev = VG_SEV_WARN;
1722	                title = "点表预警";
1723	            }
1724	            else {
1725	                sev = VG_SEV_OK;
1726	                title = NULL;
1727	            }
1728	            if(s->severity != sev) {
1729	                s->severity = sev;
1730	                changed = true;
1731	            }
1732	            rank = vg_alarm_kind_rank(kind);
1733	            if(title != NULL &&
1734	               (!s_alarm.active ||
1735	                strcmp(s_alarm.sensor_id, s->id) == 0 ||
1736	                rank > vg_alarm_kind_rank(
1737	                    s_alarm.severity == VG_SEV_CRIT ? VG_ALARM_KIND_CRIT :
1738	                    s_alarm.severity == VG_SEV_OFFLINE ? VG_ALARM_KIND_OFFLINE :
1739	                    s_alarm.severity == VG_SEV_WARN ? VG_ALARM_KIND_WARN :
1740	                    VG_ALARM_KIND_NONE))) {
1741	                char titled[VG_ALARM_TITLE_MAX];
1742	
1743	                lv_snprintf(titled, sizeof(titled), "%s %s", s->name, title);
1744	                set_alarm_from_sensor(s, sev, titled, thr,
1745	                                     s_alarm.active &&
1746	                                     strcmp(s_alarm.sensor_id, s->id) == 0 ?
1747	                                     s_alarm.duration_sec : 0);
1748	                changed = true;
1749	            }
1750	        }
1751	#else
1752	        s->severity = VG_SEV_OK;
1753	#endif
1754	        if(s->history_len < VG_HISTORY_LEN) {
1755	            s->history[s->history_len++] = value;
1756	        }
1757	        else {
1758	            memmove(&s->history[0], &s->history[1],
1759	                    (VG_HISTORY_LEN - 1) * sizeof(float));
1760	            s->history[VG_HISTORY_LEN - 1] = value;
1761	        }
1762	    }
1763	    else {
1764	        uint8_t prev_streak = s->fail_streak;
1765	
1766	        if(s->fail_streak < 255) {
1767	            s->fail_streak++;
1768	        }
1769	        if(s->age_sec < 100000) {
1770	            s->age_sec++;
1771	        }
1772	        s->quality_pct = 0;
1773	#ifdef VG_HMI_BOARD
1774	        {
1775	            struct vg_alarm_rule rule;
1776	            enum vg_alarm_kind kind;
1777	            float thr = 0.0f;
1778	
1779	            memset(&rule, 0, sizeof(rule));
1780	            strncpy(rule.cmp, s->cmp, sizeof(rule.cmp) - 1);
1781	            rule.has_warn = s->has_warn;
1782	            rule.has_crit = s->has_crit;
1783	            rule.warn = s->thr_warn;
1784	            rule.crit = s->thr_crit;
1785	            rule.fail_n = s->fail_n;
1786	            kind = vg_alarm_eval(&rule, 0, s->fail_streak, s->value, &thr);
1787	            vg_offline_win_push(s, true);
1788	            if(kind == VG_ALARM_KIND_OFFLINE && vg_offline_win_down(s)) {
1789	                if(s->online || s->severity != VG_SEV_OFFLINE) {
1790	                    changed = true;
1791	                }
1792	                s->online = false;
1793	                s->severity = VG_SEV_OFFLINE;
1794	                if(!s_alarm.active ||
1795	                   strcmp(s_alarm.sensor_id, s->id) == 0 ||
1796	                   vg_alarm_kind_rank(VG_ALARM_KIND_OFFLINE) >
1797	                   vg_alarm_kind_rank(
1798	                       s_alarm.severity == VG_SEV_CRIT ? VG_ALARM_KIND_CRIT :
1799	                       s_alarm.severity == VG_SEV_OFFLINE ? VG_ALARM_KIND_OFFLINE :
1800	                       s_alarm.severity == VG_SEV_WARN ? VG_ALARM_KIND_WARN :
1801	                       VG_ALARM_KIND_NONE)) {
1802	                    char titled[VG_ALARM_TITLE_MAX];
1803	
1804	                    lv_snprintf(titled, sizeof(titled), "%s 离线", s->name);
1805	                    set_alarm_from_sensor(s, VG_SEV_OFFLINE, titled, 0.0f,
1806	                                         s_alarm.active &&
1807	                                         strcmp(s_alarm.sensor_id, s->id) == 0 ?
1808	                                         s_alarm.duration_sec : 0);
1809	                    changed = true;
1810	                }
1811	            }
1812	            else if(prev_streak == 0) {
1813	                changed = true;
1814	            }
1815	        }
1816	#else
1817	        s->online = false;
1818	        s->severity = VG_SEV_OFFLINE;
1819	        changed = true;
1820	#endif
1821	    }
1822	    return changed;
1823	}
