88	/* Signature of visible set: filter + ids (order). Values change every tick — not in sig. */
89	static void build_list_sig(char * out, size_t n)
90	{
91	    uint16_t cnt = vg_model_home_sensor_count();
92	    uint16_t i;
93	    size_t used = 0;
94	    int w;
95	
96	    w = lv_snprintf(out, n, "%d:%u|", (int)vg_model_get_home_filter(), (unsigned)cnt);
97	    if(w < 0) {
98	        out[0] = '\0';
99	        return;
100	    }
101	    used = (size_t)w;
102	    for(i = 0; i < cnt && used + 1 < n; i++) {
103	        const vg_sensor_t * s = vg_model_home_sensor_at(i);
104	        if(s == NULL) continue;
105	        w = lv_snprintf(out + used, n - used, "%s,", s->id);
106	        if(w < 0) break;
107	        used += (size_t)w;
108	    }
109	}
