130	static lv_obj_t * make_sensor_tile(lv_obj_t * parent, const vg_sensor_t * s, uint16_t idx)
131	{
132	    char vbuf[20];
133	    lv_obj_t * tile;
134	    lv_obj_t * name;
135	    lv_obj_t * val;
136	
137	    /*
138	     * Plain obj tile (stacking recipe as vg_page_logs rows): fixed touch
139	     * height, flex row of name + value; severity carried by the left
140	     * accent border and the value color instead of a text label.
141	     */
142	    tile = lv_obj_create(parent);
143	    lv_obj_remove_flag(tile, LV_OBJ_FLAG_SCROLLABLE);
144	    lv_obj_add_flag(tile, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_CLICK_FOCUSABLE);
145	    lv_obj_set_height(tile, VG_MIN_TOUCH_H);
146	    lv_obj_set_flex_grow(tile, 1);
147	    lv_obj_set_style_radius(tile, VG_CARD_RADIUS, 0);
148	    lv_obj_set_style_border_side(tile, LV_BORDER_SIDE_LEFT, 0);
149	    lv_obj_set_style_border_width(tile, 4, 0);
150	    lv_obj_set_style_border_color(tile, vg_color_severity(s->severity), 0);
151	    /* Zebra by grid row (idx >> 1) so both tiles of a pair match */
152	    lv_obj_set_style_bg_color(tile, ((idx >> 1) & 1) ? lv_color_hex(0x1E2228) : vg_color_surface(), 0);
153	    lv_obj_set_style_bg_opa(tile, LV_OPA_COVER, 0);
154	    lv_obj_set_style_bg_color(tile, lv_color_hex(0x2A3138), LV_STATE_PRESSED);
155	    lv_obj_set_style_pad_hor(tile, 8, 0);
156	    lv_obj_set_style_pad_ver(tile, 0, 0);
157	    lv_obj_set_flex_flow(tile, LV_FLEX_FLOW_ROW);
158	    lv_obj_set_flex_align(tile, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
159	    lv_obj_set_style_pad_column(tile, 6, 0);
160	    lv_obj_add_event_cb(tile, on_row, LV_EVENT_CLICKED, (void *)s->id);
161	
162	    name = lv_label_create(tile);
163	    lv_label_set_long_mode(name, LV_LABEL_LONG_DOT);
164	    lv_obj_set_flex_grow(name, 1);
165	    lv_label_set_text(name, s->name);
166	    lv_obj_set_style_text_font(name, vg_font_ui(), 0);
167	    lv_obj_set_style_text_color(name, s->online ? vg_color_text() : vg_color_muted(), 0);
168	
169	    val = lv_label_create(tile);
170	    fmt_value_unit(vbuf, sizeof(vbuf), s->value, s->unit,
171	                   s->online && s->quality_pct > 0);
172	    lv_label_set_text(val, vbuf);
173	    lv_obj_set_style_text_font(val, vg_font_metric(), 0);
174	    lv_obj_set_style_text_color(val, vg_color_severity(s->severity), 0);
175	
176	    /* Store value label for in-place refresh; name is child 0 */
177	    lv_obj_set_user_data(tile, val);
178	    return tile;
179	}
